{
  "findings": [
    {
      "ref": "[D527]",
      "area": "contact",
      "claim": "A parent reports that voice chat can be turned off in Fortnite: Battle Royale.",
      "stance": "mitigation",
      "quote": "How do you turn off voice chat in Fortnite: Battle Royale?"
    },
    {
      "ref": "[D527]",
      "area": "money",
      "claim": "A parent reports that Fortnite encourages in-app purchases and uses a Battle Pass subscription model.",
      "stance": "risk",
      "quote": "The Premium Battle Pass requires a $10 subscription that lets players compete on more levels and win exclusive game skins/costumes. Epic's partnerships with popular entities including Marvel, the Mandalorian, Predator, and Tron mean they frequently introduce new characters, costumes, and other crave-worthy elements—keeping players' interest up and their money coming in."
    },
    {
      "ref": "[D527]",
      "area": "data",
      "claim": "A parent reports that the game collects age information and may share data with third parties for advertising.",
      "stance": "risk",
      "quote": "Accounts for users under 13 are automatically assigned a \"cabined account,\" where parents and caregivers have to consent to their child getting access to certain features. These include in-game purchases and chatting. Keep in mind that the game determines a user's age based on the date of birth they enter when setting up an account."
    },
    {
      "ref": "[D527]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works by requiring parental consent for users under 13.",
      "stance": "mitigation",
      "quote": "Children below that age are automatically assigned a \"cabined account,\" where parents and caregivers have to consent to their child getting access to certain features."
    },
    {
      "ref": "[D527]",
      "area": "content",
      "claim": "A parent reports that the game features cartoonish violence without blood.",
      "stance": "neutral",
      "quote": "Fortnite: Battle Royale is loaded with violence, but it's all cartoonish, rather than bloody or gory. Since the object is to be the last one standing, you'll constantly shoot other players and dodge fatal storms. However, there's no blood; defeated enemies simply vanish."
    },
    {
      "ref": "[D527]",
      "area": "developer_record",
      "claim": "A parent reports that Epic Games has faced regulatory scrutiny over data collection for children.",
      "stance": "risk",
      "quote": "Keep in mind that the game determines a user's age based on the date of birth they enter when setting up an account."
    }
  ]
}
